import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AdminService } from '../../../core/services/admin.service';
import { Department, Doctor } from '../../../core/models';

@Component({
  selector: 'app-doctors',
  templateUrl: './doctors.component.html'
})
export class DoctorsComponent implements OnInit {

  doctors: Doctor[] = [];
  departments: Department[] = [];
  form: FormGroup;
  loading = false;
  success = '';
  error = '';

  constructor(private fb: FormBuilder, private adminService: AdminService) {
    this.form = this.fb.group({
      name:           ['', [Validators.required, Validators.minLength(2)]],
      email:          ['', [Validators.required, Validators.email]],
      password:       ['', [Validators.required, Validators.minLength(6)]],
      departmentId:   [null, Validators.required],
      specialization: ['']
    });
  }

  ngOnInit(): void {
    this.adminService.getDoctors().subscribe(d => this.doctors = d);
    this.adminService.getDepartments().subscribe(d => this.departments = d.filter(dep => dep.active));
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.success = '';

    this.adminService.createDoctor(this.form.value).subscribe({
      next: () => {
        this.success = 'Doctor created successfully.';
        this.form.reset();
        this.adminService.getDoctors().subscribe(d => this.doctors = d);
        this.loading = false;
      },
      error: err => {
        this.error = err.error?.message ?? 'Failed to create doctor.';
        this.loading = false;
      }
    });
  }
}
<div class="page-header">
  <h2>Doctors</h2>
  <p>Register doctors and assign them to departments</p>
</div>

<div class="card" style="max-width:520px;">
  <h4 style="margin-bottom:16px;">Add Doctor</h4>
  <div *ngIf="success" class="alert alert-success">{{ success }}</div>
  <div *ngIf="error"   class="alert alert-danger">{{ error }}</div>

  <form [formGroup]="form" (ngSubmit)="submit()">
    <div class="form-group">
      <label>Full Name *</label>
      <input formControlName="name" placeholder="Dr. Jane Smith">
    </div>
    <div class="form-group">
      <label>Email *</label>
      <input type="email" formControlName="email" placeholder="doctor@hospital.com">
    </div>
    <div class="form-group">
      <label>Password *</label>
      <input type="password" formControlName="password" placeholder="Min 6 characters">
    </div>
    <div class="form-group">
      <label>Department *</label>
      <select formControlName="departmentId">
        <option [ngValue]="null" disabled>Select department</option>
        <option *ngFor="let d of departments" [value]="d.id">{{ d.name }}</option>
      </select>
    </div>
    <div class="form-group">
      <label>Specialization</label>
      <input formControlName="specialization" placeholder="e.g., Cardiologist">
    </div>
    <button class="btn btn-primary" [disabled]="loading">
      {{ loading ? 'Creating...' : 'Create Doctor' }}
    </button>
  </form>
</div>

<div class="card">
  <h4 style="margin-bottom:16px;">All Doctors ({{ doctors.length }})</h4>
  <table>
    <thead>
      <tr><th>Name</th><th>Email</th><th>Department</th><th>Specialization</th><th>Available</th></tr>
    </thead>
    <tbody>
      <tr *ngFor="let d of doctors">
        <td>{{ d.name }}</td>
        <td>{{ d.email }}</td>
        <td>{{ d.department.name }}</td>
        <td>{{ d.specialization || '—' }}</td>
        <td>
          <span class="badge" [class.badge-completed]="d.available"
                [class.badge-waiting]="!d.available">
            {{ d.available ? 'Yes' : 'No' }}
          </span>
        </td>
      </tr>
    </tbody>
  </table>
</div>
